query AminalsList($first: Int = 100, $address: String = "") {
  aminals(limit: $first, orderBy: "aminalIndex", orderDirection: "asc") {
    items {
      id
      contractAddress
      aminalIndex
      parentOne {
        id
        contractAddress
        aminalIndex
      }
      parentTwo {
        id
        contractAddress
        aminalIndex
      }
      energy
      totalLove
      ethBalance
      blockTimestamp
      tokenURI
      traits
      lovers(where: {userId: $address}, limit: 1) {
        items {
          love
        }
      }
    }
  }
}

