      items {
        id
        aminal {
          id
          contractAddress
          tokenURI
          totalLove
          energy
          ethBalance
          blockTimestamp
        }
        love
      }
    }
    genesCreated(limit: 100) {
      items {
        id
        tokenId
        traitType
        name
        description
        svg
        totalEarnings
        blockTimestamp
        payouts(limit: 100) {
          items {
            id
            amount
            auctionId
            blockTimestamp
          }
        }
      }
    }
    genesOwned(limit: 100) {
      items {
        id
        tokenId
        traitType
        name
        description
        svg
        totalEarnings
